/// `PluginObjectBlob` now lives in the `op-blob` crate, so the constructors
/// are free functions (inherent impls on a foreign type are not allowed).
pub type ZeroClawRouterObjectBlob = PluginObjectBlob;

/// Build the immutable object blob from the plugin-owned zeroclow_router schema.
pub fn from_plugin_schema() -> ZeroClawRouterObjectBlob {
    from_schema(op_plugins::state_plugins::tched_router::tched_router_plugin_schema())
}

pub fn from_schema(schema: PluginSchema) -> ZeroClawRouterObjectBlob {
    blobify_plugin_schema(ZEROCLOW_ROUTER_PLUGIN_ID, schema)
}

